"""Residentado Médico 2020 · Anatomía Patológica, preguntas 26-50"""
import lote08_base as B
L = []
ROB = "Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)"
WHO_ST = "WHO Classification of Tumours, Soft Tissue and Bone Tumours 5.ª ed. (2020)"
WHO_HAEM = "Alaggio R et al. Leukemia 2022;36:1720-48 (WHO 5.ª ed. de neoplasias hematolinfoides)"
def Q(n, tema, cat, c, f, nota=None, **kw): B.hacer(L, "ANATOMIA_PATOLOGICA", n, tema, cat, c, f, nota, **kw)

Q(26, "Grado histológico del adenocarcinoma de colon", "Patología digestiva",
  "El grado histológico expresa la diferenciación del tumor y es independiente de la extensión anatómica. En el adenocarcinoma colorrectal la OMS (5.ª edición, 2019) lo establece por el porcentaje de formación glandular: bajo grado si hay 50 % o más de glándulas y alto grado si hay menos del 50 %, equivalente a la división clásica en bien, moderadamente y pobremente diferenciado. Los rasgos citológicos de agresividad, como el pleomorfismo, la necrosis y la actividad mitótica, acompañan al alto grado, y por eso la clave oficial señala el recuento de figuras mitóticas por campo de gran aumento como dato del grado. Las otras opciones pertenecen a la estadificación TNM: tamaño o profundidad de invasión (pT), ganglios positivos (pN) y metástasis (pM). La estadificación define la conducta: las guías ESMO y SEOM-GEMCAD de 2023 indican quimioterapia adyuvante en el estadio III y consideran en el estadio II factores de riesgo como alto grado, T4, menos de 12 ganglios examinados e invasión vascular o perineural. En todo cáncer colorrectal se determina la inestabilidad de microsatélites o la deficiencia de reparación del ADN, y en el metastásico RAS y BRAF. Perla: se examinan al menos 12 ganglios, y el alto grado pesa menos si el tumor tiene inestabilidad de microsatélites.",
  "Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); WHO Classification of Tumours, Digestive System Tumours 5.ª ed. (2019); Cervantes A et al. Ann Oncol 2023;34:10-32 (guía ESMO del cáncer colorrectal metastásico); Pericay C et al. Clin Transl Oncol 2024;26:2812-2825 (guía SEOM-GEMCAD-TTD de tratamiento adyuvante del cáncer de colon, 2023)",
  "Según la OMS 2019 el grado del cáncer colorrectal se basa en la formación glandular y no en el recuento mitótico; se mantiene la clave oficial (A) porque las demás opciones son de estadificación.")

Q(27, "Células NK frente a infección viral con baja expresión de CPH I", "Inmunología",
  "Muchos virus, entre ellos los herpesvirus y el citomegalovirus, reducen la expresión de moléculas del complejo mayor de histocompatibilidad (CPH) de clase I en la célula infectada para escapar de los linfocitos T citotóxicos CD8+. Los linfocitos citolíticos naturales (NK) son los efectores de la inmunidad innata que resuelven esa maniobra, según la revisión de Mace de 2023 en J Allergy Clin Immunol. Sus receptores inhibidores (KIR y CD94/NKG2A) reconocen CPH I propio, y la pérdida de CPH I libera la inhibición, el llamado reconocimiento de lo propio ausente. Junto con ligandos de estrés que activan receptores como NKG2D, esto desencadena la liberación de perforina y granzimas, la citotoxicidad dependiente de anticuerpos y la secreción de interferón gamma. Actúan en las primeras horas, antes de que se expanda la respuesta adaptativa, y se describen poblaciones NK de memoria o adaptativas tras la infección por citomegalovirus, como señala la revisión de Yu de 2023 sobre células NK antivirales y antitumorales. Los linfocitos CD4+ reconocen CPH II y colaboran con citocinas; los linfocitos B producen anticuerpos con retraso; los macrófagos y las células dendríticas fagocitan y presentan antígeno, pero no son los citotóxicos principales. Perla: las células NK también destruyen células tumorales que han perdido CPH I.",
  "Mace EM. J Allergy Clin Immunol 2023;151:371-385 (células NK humanas); Yu J et al. Semin Immunol 2023;67:101749 (células NK reactivas a virus y tumores); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Abbas AK et al. Inmunología Celular y Molecular 10.ª ed. (2022)")

Q(28, "Angiofibroma de células gigantes", "Patología de partes blandas y órbita",
  "El angiofibroma de células gigantes es una neoplasia mesenquimal benigna rara, descrita primero en la órbita y los párpados de adultos y luego en otras localizaciones, como la mucosa oral y las partes blandas, según series y casos publicados en 2023 y 2024; se ha descrito también en asociación con esclerosis tuberosa. Histológicamente muestra un estroma de células fusiformes o redondeadas de aspecto inocuo, con celularidad variable, espacios angiectoides seudovasculares revestidos por células estromales multinucleadas y cambios quísticos o hemorrágicos. Por inmunohistoquímica expresa CD34, con frecuencia CD99 y bcl-2, y es negativo para marcadores epiteliales y de músculo liso. Comparte la positividad para CD34 con el fibroblastoma de células gigantes y con el dermatofibrosarcoma protuberans, pero es una entidad distinta: el fibroblastoma de células gigantes afecta al tronco de niños y varones jóvenes, y el dermatofibrosarcoma muestra patrón estoriforme y fusión COL1A1-PDGFB. El fibrohistiocitoma benigno suele ser CD34 negativo y expresar factor XIIIa, y el sarcoma sinovial monofásico forma fascículos de células fusiformes con TLE1 y t(X;18). El tratamiento es la escisión completa, con recurrencia infrecuente. Perla: CD34 positivo, células gigantes multinucleadas y espacios vasculares en un tumor palpebral u orbitario orientan a este diagnóstico.",
  "WHO Classification of Tumours, Soft Tissue and Bone Tumours 5.ª ed. (2020); Sun Q et al. Diagn Pathol 2024;19:50 (angiofibroma de células gigantes gingival en esclerosis tuberosa, con revisión); Dudde F et al. Anticancer Res 2023;43:1869-1871 (angiofibroma de células gigantes de la mucosa bucal)",
  "El angiofibroma de células gigantes ya no se considera exclusivamente orbitario: hay descripciones en mucosa oral y partes blandas. La clave oficial (E) se mantiene.")

Q(29, "Lipoblastoma", "Patología de partes blandas",
  "El lipoblastoma es un tumor adiposo benigno de la lactancia y la primera infancia, casi siempre antes de los 3 años y más frecuente en varones, que se origina de tejido adiposo embrionario. Se presenta como una masa de crecimiento rápido en extremidades, tronco, cabeza y cuello, con una forma circunscrita y otra infiltrante, la lipoblastomatosis. Microscópicamente forma lóbulos separados por tabiques fibrosos, con lipoblastos en distintas etapas de maduración, abundante estroma mixoide con capilares ramificados en «pata de gallina» y adipocitos maduros; las áreas mixoides son características. Se define genéticamente por reordenamientos del gen PLAG1 en 8q11-13, con diversos genes compañeros, como EEF1A1::PLAG1 en casos descritos en 2024, y su detección por FISH o inmunohistoquímica ayuda en los casos dudosos. Es benigno: no metastatiza ni se transforma y el pronóstico es excelente, de modo que las opciones sobre metástasis, malignización, mal pronóstico y ausencia de estroma mixoide son falsas. El diagnóstico diferencial principal es el liposarcoma mixoide, raro en niños pequeños, con t(12;16) y FUS::DDIT3. El tratamiento es la escisión completa; la recidiva local ocurre en cerca del 15-25 %, sobre todo en la forma infiltrante. Perla: una masa adiposa de crecimiento rápido en un lactante es lipoblastoma hasta demostrar lo contrario.",
  "WHO Classification of Tumours, Soft Tissue and Bone Tumours 5.ª ed. (2020); Deolet E et al. Genes Chromosomes Cancer 2024;63:e23225 (lipoblastoma con fusión EEF1A1::PLAG1); Lanceta J et al. Mol Cytogenet 2023;16:32 (lipoblastoma con reordenamiento complejo de PLAG1); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)")

Q(30, "VPH de alto riesgo", "Patología ginecológica",
  "Los papilomavirus humanos se clasifican según su potencial oncogénico. Los tipos de alto riesgo comprenden 16, 18, 31, 33, 35, 39, 45, 51, 52, 56, 58, 59, 66 y 68, a los que la IARC añade otros de probable riesgo. Estos genotipos expresan las oncoproteínas E6 y E7 que inactivan p53 y la proteína del retinoblastoma (Rb), lo que altera el control del ciclo celular, y se integran al genoma del huésped; el VPH 16 se asocia con cerca del 50-60 % de los carcinomas de cuello uterino y el 18 con el adenocarcinoma. El tipo 31 es de alto riesgo y produce lesión intraepitelial escamosa de alto grado y carcinoma. Los tipos 6 y 11 son de bajo riesgo y causan condilomas acuminados y papilomatosis respiratoria recurrente, mientras que los tipos 40 y 42 también se agrupan entre los de bajo riesgo y se asocian con lesiones benignas anogenitales. El tamizaje se hace con prueba de VPH o citología, y la vacunación nonavalente cubre los tipos 6, 11, 16, 18, 31, 33, 45, 52 y 58. Perla: la infección persistente por un tipo de alto riesgo, y no la transitoria, es la que conduce al cáncer.",
  ROB + "; Muñoz N et al. N Engl J Med 2003;348:518-27 (clasificación epidemiológica de los tipos de VPH); Directiva 165-2025 (cáncer de cuello uterino)")

Q(31, "Endometriosis vesical", "Patología ginecológica",
  "La endometriosis es la presencia de glándulas y estroma endometrial fuera del útero, y la localización vesical es la más frecuente del tracto urinario, aunque es rara. Se manifiesta con dolor suprapúbico y síntomas urinarios cíclicos, y la hematuria cíclica con la menstruación, presente en una minoría de las pacientes, es muy sugestiva. Entre las teorías etiológicas figuran la menstruación retrógrada, la metaplasia celómica y la diseminación linfática o vascular. Como el tejido responde a las hormonas ováricas, sangra en cada ciclo, por lo que el examen histológico muestra glándulas endometriales, estroma y macrófagos con hemosiderina, signo de hemorragia repetida; la cistoscopia revela un nódulo azulado o violáceo, típicamente en la cúpula o la base. Las demás opciones no explican la ciclicidad: los fascículos entrelazados de músculo liso corresponden a un leiomioma, los pólipos revestidos de células neoplásicas a un carcinoma urotelial papilar, ligado al tabaco, la esquistosomiasis por Schistosoma haematobium produce hematuria en zonas endémicas sin relación con la regla y las calcificaciones displásicas no son específicas. El tratamiento de las lesiones sintomáticas es la resección, por vía laparoscópica o robótica con cistectomía parcial o resección transuretral, además de supresión hormonal, según series y revisiones sistemáticas de 2023 y 2025. Perla: hematuria que coincide con la regla equivale a endometriosis vesical hasta demostrar lo contrario.",
  "Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Yan H et al. J Minim Invasive Gynecol 2025;32:22-30 (endometriosis vesical, síntomas y desenlaces del embarazo); Piriyev E et al. In Vivo 2023;37:357-365 (abordaje laparoscópico de la endometriosis vesical); Zondervan KT et al. N Engl J Med 2020;382:1244-56")

Q(32, "Quiste periapical", "Patología oral",
  "El quiste periapical (radicular) es el quiste odontogénico inflamatorio más frecuente de los maxilares. Se origina por la proliferación de los restos epiteliales de Malassez, estimulados por la inflamación crónica periapical que sigue a la necrosis pulpar de un diente con caries profunda o traumatismo. La revisión de Rios Osorio de 2023 en Eur Endod J distingue el quiste verdadero, con luz completamente cerrada por el epitelio, del quiste en bolsa, comunicado con el conducto radicular, diferencia con implicancias para su resolución tras el tratamiento endodóntico. Aparece como una imagen radiolúcida circunscrita en el ápice de un diente no vital, con pérdida de la lámina dura. Histológicamente, la cápsula fibrosa contiene un denso infiltrado inflamatorio crónico y el revestimiento es de epitelio escamoso estratificado no queratinizado, con cristales de colesterol, cuerpos de Rushton y calcificación distrófica. La OMS 2022 lo clasifica entre los quistes inflamatorios de los maxilares. El quiste periodontal lateral aparece junto a la raíz de un diente vital, con epitelio delgado y claro; el del conducto nasopalatino se halla en la línea media; y el quiste ortoqueratinizante y el tumor odontogénico queratoquístico tienen una capa queratinizada ondulada con empalizada basal. Perla: el tratamiento inicial es endodoncia o extracción; si la lesión persiste, se hace enucleación con apicectomía.",
  "Rios Osorio N et al. Eur Endod J 2023;8:20-36 (paradigma del quiste radicular inflamatorio); WHO Classification of Head and Neck Tumours 5.ª ed. (2022); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Neville BW et al. Oral and Maxillofacial Pathology 4.ª ed. (2016)")

Q(33, "Clasificación FAB de la leucemia mieloide aguda", "Hematopatología",
  "La clasificación franco-americano-británica (FAB) divide las leucemias mieloides agudas (LMA) en ocho subtipos según la morfología y la citoquímica de los blastos: M0 mínimamente diferenciada, sin mieloperoxidasa (menos del 3 %); M1 sin maduración, con 90 % o más de blastos en la médula no eritroide y mieloperoxidasa positiva; M2 con maduración, asociada a t(8;21); M3 promielocítica, con t(15;17) y PML::RARA; M4 mielomonocítica, con M4Eo e inv(16); M5 monocítica; M6 eritroide y M7 megacarioblástica. La LMA sin maduración corresponde, por tanto, a M1. Las clasificaciones vigentes ya no usan el esquema FAB: la OMS de 2022 (5.ª edición) y el Consenso Internacional (ICC 2022) se basan en anomalías genéticas recurrentes, y la comparación de Lee y colaboradores de 2024 muestra que difieren en el umbral de blastos: la OMS exige 20 % salvo para las LMA con defectos genéticos definitorios, mientras que el ICC admite 10-19 % de blastos como síndrome mielodisplásico/LMA. El diagnóstico requiere citometría de flujo, citogenética y biología molecular, y los bastones de Auer son típicos. Perla: la M3 es una urgencia por la coagulopatía y se trata de inmediato con ácido transretinoico, sin esperar la confirmación genética.",
  "Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Bennett JM et al. Br J Haematol 1976;33:451-8 (clasificación FAB); Alaggio R et al. Leukemia 2022;36:1720-48 (WHO 5.ª ed. de neoplasias hematolinfoides); Lee WH et al. Blood Cancer J 2024;14:57 (comparación de la clasificación OMS 2022 y el consenso internacional en la LMA)", "El esquema FAB es histórico; la OMS 2022 y el ICC 2022 clasifican por genética. La clave oficial (B, M1) se mantiene.")

Q(34, "Mutación SF3B1 en el síndrome mielodisplásico", "Hematopatología",
  "Los síndromes mielodisplásicos son neoplasias clonales de la célula madre hematopoyética con hematopoyesis ineficaz, displasia y riesgo de evolución a leucemia. Las mutaciones de los genes del empalme son frecuentes, y SF3B1 se asocia con sideroblastos en anillo, displasia eritroide predominante y pronóstico favorable, con supervivencia prolongada y bajo riesgo de transformación. La OMS 2022 (5.ª edición) lo reconoce como entidad propia, el síndrome mielodisplásico con blastos bajos y mutación de SF3B1, y el consenso ICC 2022 como síndrome mielodisplásico con SF3B1 mutado. El índice IPSS-M (2022) integra las mutaciones con la citopenia y la citogenética. En 2023, el ensayo COMMANDS publicado en Lancet mostró que luspatercept fue superior a epoetina alfa en pacientes de bajo riesgo con anemia que no habían recibido estimulantes de la eritropoyesis, y es el tratamiento de la anemia en este grupo, sobre todo si hay SF3B1 o sideroblastos en anillo. Las otras mutaciones empeoran el pronóstico: TP53 multi-hit indica alto riesgo y resistencia al tratamiento; RUNX1 y NRAS se relacionan con progresión a leucemia; SRSF2, también del empalme, se vincula con la leucemia mielomonocítica crónica y peor evolución. Perla: ante anemia macrocítica con sideroblastos en anillo se busca SF3B1, que predice una evolución indolente.",
  "Platzbecker U et al. Lancet 2023;402:373-385 (luspatercept frente a epoetina alfa en síndrome mielodisplásico de bajo riesgo, ensayo COMMANDS); Alaggio R et al. Leukemia 2022;36:1720-48 (WHO 5.ª ed. de neoplasias hematolinfoides); Bernard E et al. NEJM Evid 2022;1(7):EVIDoa2200008 (IPSS-M); Papaemmanuil E et al. Blood 2013;122:3616-27; Malcovati L et al. Blood 2015;126:233-41")

Q(35, "Neurofibroma difuso", "Patología de nervios periféricos",
  "El neurofibroma es una neoplasia benigna de la vaina nerviosa formada por células de Schwann, fibroblastos, células perineurales, mastocitos y matriz colágena mixoide, con haces de colágeno en «alambre» o «zanahoria». La OMS 2020 reconoce las variantes localizada, difusa, plexiforme y masiva de partes blandas, además de la lesión intermedia llamada neoplasia neurofibromatosa atípica de potencial biológico incierto. El neurofibroma difuso afecta sobre todo a niños y adultos jóvenes, en la dermis y el tejido subcutáneo de cabeza y cuello, y forma una placa que infiltra los septos y rodea los anexos sin destruirlos, con aspecto de «panal». Su rasgo característico es la presencia de estructuras seudotáctiles, es decir, corpúsculos de Wagner-Meissner, en cerca del 40 % de los casos. Los múltiples nódulos intraneurales corresponden al neurofibroma plexiforme, patognomónico de la neurofibromatosis tipo 1; el cambio mixoide es común a muchos tumores, y la disposición estoriforme y la hialinización son propias del dermatofibrosarcoma protuberans. En el plexiforme sintomático e inoperable, los ensayos de fase 2 publicados en 2025 con inhibidores de MEK, selumetinib en adultos y mirdametinib en adultos y niños, mostraron respuestas de volumen tumoral. Perla: el plexiforme puede malignizarse a tumor maligno de la vaina nerviosa periférica; el difuso casi nunca.",
  "WHO Classification of Tumours, Soft Tissue and Bone Tumours 5.ª ed. (2020); Gross AM et al. Nat Med 2025;31:105-115 (selumetinib en adultos con NF1 y neurofibroma plexiforme inoperable); Moertel CL et al. J Clin Oncol 2025;43:716-729 (ensayo ReNeu de mirdametinib); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)")

Q(36, "Struma ovarii", "Patología ovárica",
  "El struma ovarii es un teratoma monodérmico especializado en el que el tejido tiroideo maduro constituye más del 50 % del tumor. Aparece en mujeres de edad media, es unilateral y se presenta como una masa sólido-quística con áreas multiloculadas de coloide, a menudo pardo verdosas. Microscópicamente reproduce folículos tiroideos con coloide, con células planas o cúbicas de núcleos redondos uniformes. Es benigno en la gran mayoría, y puede cursar con hipertiroidismo (alrededor del 5-8 %) o con ascitis y derrame pleural (síndrome de seudo-Meigs). La revisión de 2023 de Tondi Resta en Endocr Pathol resume las neoplasias que pueden surgir en el struma, sobre todo el carcinoma papilar y el carcinoma folicular bien diferenciado de origen ovárico, que obligan a evaluar riesgo y, en casos seleccionados, a tiroidectomía y yodo radiactivo. El disgerminoma muestra células claras en nidos con septos linfocitarios; el teratoma inmaduro, neuroepitelio inmaduro; el tumor de Sertoli-Leydig produce andrógenos y recuerda túbulos testiculares; y el tumor del saco vitelino exhibe patrón reticular, cuerpos de Schiller-Duval y alfafetoproteína. Se confirma con tiroglobulina y TTF-1. El tratamiento del struma benigno es la cistectomía o la salpingooforectomía. Perla: hipertiroidismo con tiroides hipocaptante y masa pélvica sugiere struma ovarii.",
  "WHO Classification of Tumours, Female Genital Tumours 5.ª ed. (2020); Tondi Resta I et al. Endocr Pathol 2023;34:455-460 (neoplasias en struma ovarii); Erkan S et al. Sisli Etfal Hastan Tip Bul 2024;58:284-290 (struma ovarii, experiencia de un centro); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)",
  "El enunciado dice «Struma ovarri» y «Sertoli-Leyding»: son errores de ortografía de la fuente; el diagnóstico es struma ovarii.")

Q(37, "Inmunohistoquímica del tumor del saco vitelino", "Patología testicular y ovárica",
  "El tumor del saco vitelino es una neoplasia de células germinales que recuerda el saco vitelino embrionario. La OMS 2022 distingue el tipo postpuberal, derivado de la neoplasia de células germinales in situ y habitualmente componente de tumores mixtos del adulto, del tipo prepuberal, frecuente en niños pequeños, que no se origina de esa lesión ni tiene isocromosoma 12p. Los patrones son reticular o microquístico, festoneado, papilar y sólido, con cuerpos de Schiller-Duval y glóbulos hialinos eosinófilos. Sintetiza alfafetoproteína (AFP), que se detecta en el suero y en el tejido, y es el marcador tumoral e inmunohistoquímico más característico. También expresa glipicano 3 y SALL4, y es negativo para OCT4, CD30 y CD117. SALL4 es sensible para todos los tumores germinales, pero no específico del saco vitelino; CD117 se expresa en el seminoma y el disgerminoma; CD30 marca el carcinoma embrionario; el EMA no es un marcador germinal. Las guías de la Asociación Europea de Urología de 2023 incluyen AFP, gonadotropina coriónica humana y LDH en el diagnóstico, el pronóstico y el seguimiento, y recomiendan orquiectomía inguinal y quimioterapia con bleomicina, etopósido y cisplatino (BEP) según el estadio. Perla: una AFP elevada con un tumor testicular que parece seminoma puro indica componente no seminomatoso.",
  "WHO Classification of Tumours, Urinary and Male Genital Tumours 5.ª ed. (2022); Patrikidou A et al. Eur Urol 2023;84:289-301 (guía EAU de cáncer testicular, actualización 2023); Fichtner A et al. Histopathology 2026;88:214-229 (patología molecular de los tumores germinales testiculares); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)")

Q(38, "Insulitis en la diabetes tipo 1", "Patología endocrina",
  "La diabetes mellitus tipo 1 es una enfermedad autoinmunitaria que destruye de manera selectiva las células beta de los islotes pancreáticos, mediada por linfocitos T CD4+ y CD8+ frente a autoantígenos como la insulina, GAD65 e IA-2, en un contexto de susceptibilidad genética (HLA-DR3 y DR4) y factores ambientales. La lesión característica de la fase inicial es la insulitis, un infiltrado de linfocitos T, con macrófagos y algunos linfocitos B, dentro y alrededor de los islotes. Al avanzar la enfermedad los islotes se atrofian y se reduce el número de células beta, hasta cerca del 80-90 % de pérdida al diagnóstico clínico. El depósito de amiloide en los islotes es propio de la diabetes tipo 2; la calcificación distrófica y la necrosis grasa se observan en la pancreatitis aguda o crónica; un mayor número de islotes aparece en hijos de madre diabética, y la fibrosis acinar con atrofia corresponde a la pancreatitis crónica. El tratamiento es la insulina, con control glucémico y vigilancia de complicaciones; los anticuerpos antiGAD son útiles para el diagnóstico. Perla: los anticuerpos, y no la insulitis, son lo que se mide en la práctica.",
  ROB + "; American Diabetes Association. Diabetes Care 2024;47(Suppl 1):S20-S42 (clasificación y diagnóstico)")

Q(39, "Sarcoma de Kaposi y HHV-8", "Patología vascular e infecciosa",
  "El sarcoma de Kaposi es una neoplasia vascular de bajo grado causada por el herpesvirus humano 8 (HHV-8, o herpesvirus asociado al sarcoma de Kaposi). Existen cuatro formas: clásica, endémica africana, iatrogénica y epidémica asociada al sida, la que corresponde a un varón homosexual con inmunodepresión. Evoluciona en tres fases: mácula o parche, placa y nódulo. La fase de mácula muestra espacios capilares irregulares y angulados, revestidos por células endoteliales con leve pleomorfismo, que rodean los vasos dérmicos preexistentes (signo del promontorio), con extravasación de eritrocitos y macrófagos con hemosiderina. La inmunohistoquímica es positiva para LANA-1 del HHV-8, CD31 y CD34, y la positividad de LANA-1 es el dato más específico. El virus herpes simple y el citomegalovirus producen lesiones ulcerosas con inclusiones, el HHV-6 el exantema súbito, y el VIH favorece el tumor por inmunodepresión pero no lo causa directamente. Las revisiones de 2023 y 2025 coinciden en que el tratamiento base es la terapia antirretroviral, que puede bastar en la enfermedad limitada, y en que la enfermedad extensa o visceral requiere quimioterapia con doxorrubicina liposomal o paclitaxel. En el Perú, la NTS 169-MINSA/2020/DGIESP regula la atención integral del adulto con VIH y el inicio de la terapia antirretroviral. Perla: el sarcoma de Kaposi es una enfermedad definitoria de sida.",
  "Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Patel R et al. Expert Rev Anti Infect Ther 2023;21:929-941 (manejo clínico de las enfermedades asociadas al herpesvirus del sarcoma de Kaposi); Bettuzzi T et al. J Med Virol 2025;97:e70294 (abordaje moderno del sarcoma de Kaposi); Htet KZ et al. Clin Dermatol 2026;44:67-77 (actualización); NTS 169-MINSA/2020/DGIESP (VIH)")

Q(40, "Hiperdiploidía en leucemia linfoblástica aguda", "Hematopatología",
  "La leucemia linfoblástica aguda de células B es la neoplasia más frecuente de la infancia, y su pronóstico depende de la edad, el recuento de leucocitos, la respuesta temprana, la enfermedad mínima residual y las alteraciones genéticas. La OMS 2022 (5.ª edición) define la LLA-B con hiperdiploidía alta (51-65 cromosomas, con ganancias de los cromosomas 4, 10, 17 y 18) y la LLA-B con ETV6::RUNX1 como subtipos de pronóstico favorable, con supervivencia superior al 90 % con quimioterapia moderna; cerca de una cuarta parte de los casos pediátricos es hiperdiploide, sobre todo entre los 2 y 10 años. Por ello la respuesta es la hiperdiploidía. Los estudios del St. Jude publicados en J Clin Oncol 2024 y la revisión de Lancet 2025 muestran que el pronóstico se reevalúa hoy según el subtipo genómico y la enfermedad mínima residual. Son de mal pronóstico el reordenamiento KMT2A (11q23), típico del lactante, la hipodiploidía con menos de 44 cromosomas y TP53 mutado, el iAMP21 y el cromosoma Filadelfia t(9;22) (BCR::ABL1), que ahora se trata con inhibidores de tirosina cinasa asociados a quimioterapia. La t(1;19) (TCF3::PBX1) es de riesgo intermedio y mejoró con terapia intensificada. Perla: ETV6::RUNX1 no se ve en el cariotipo convencional y requiere FISH o PCR.",
  "Alaggio R et al. Leukemia 2022;36:1720-48 (WHO 5.ª ed. de neoplasias hematolinfoides); Chang TC et al. J Clin Oncol 2024;42:3491-3503 (determinantes genómicos del desenlace en la leucemia linfoblástica aguda); Kantarjian H et al. Lancet 2025;406:950-962 (leucemia linfocítica aguda); Pui CH, Evans WE. N Engl J Med 2006;354:166-78")

Q(41, "AMACR en el carcinoma renal papilar", "Patología renal",
  "La alfa-metilacil-CoA racemasa (AMACR, P504S) es una enzima de la oxidación de ácidos grasos que se usa como marcador inmunohistoquímico en el adenocarcinoma de próstata. En los tumores renales se expresa de forma difusa y fuerte, con patrón citoplásmico granular, en el carcinoma papilar de células renales. La clasificación de la OMS 2022 (5.ª edición) ya no subdivide el carcinoma papilar en tipos 1 y 2, porque el tipo 2 resultó heterogéneo; la positividad de AMACR sigue siendo útil en ambos, junto con CK7 y las trisomías de los cromosomas 7 y 17. La positividad no es exclusiva: el estudio de Rotterova de 2024 documenta reactividad de AMACR en una proporción de carcinomas de células claras y de otros subtipos, por lo que el panel se interpreta en conjunto. El carcinoma de células claras, el más frecuente, es positivo para anhidrasa carbónica IX, CD10 y PAX8 y habitualmente negativo o focal para AMACR; el carcinoma cromófobo expresa CD117 y CK7 con AMACR negativo; el carcinoma de los conductos colectores es agresivo, con patrón tubular desmoplásico; y el carcinoma medular se asocia con hemoglobinopatía falciforme y pérdida de SMARCB1 (INI1). Perla: la mutación de MET se asocia con el carcinoma papilar hereditario.",
  "Moch H et al. Eur Urol 2022;82:458-468 (clasificación OMS 2022 de tumores del sistema urinario y genitales masculinos); Rotterova P et al. Ann Diagn Pathol 2024;71:152297 (reactividad de AMACR en carcinomas renales de células claras y otros subtipos); WHO Classification of Tumours, Urinary and Male Genital Tumours 5.ª ed. (2022); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)")

Q(42, "Síndrome de Gilbert", "Patología hepática",
  "El síndrome de Gilbert es la causa más frecuente de hiperbilirrubinemia indirecta hereditaria benigna y afecta a cerca del 5-10 % de la población. Se debe a una menor actividad de la enzima UDP-glucuronosiltransferasa 1A1 (UGT1A1), con más frecuencia por una expansión repetida TA en su promotor (UGT1A1*28), con reducción de la conjugación hepática de bilirrubina. La revisión de Vítek de 2023 en J Hepatol subraya que es una variante fisiológica, más que una enfermedad, y que se asocia en estudios observacionales a menor riesgo cardiovascular, aunque aumenta la toxicidad de fármacos metabolizados por UGT1A1, como el irinotecán. Los pacientes tienen ictericia leve e intermitente, desencadenada por ayuno, estrés, enfermedad intercurrente o ejercicio, con bilirrubina total habitualmente menor de 3-5 mg/dl a expensas de la fracción no conjugada. La bilirrubina indirecta se une a la albúmina y no se filtra por el glomérulo, por lo que no hay bilirrubinuria, y las transaminasas, la fosfatasa alcalina y el hemograma son normales. Por eso la histología hepática, que no se requiere, muestra parénquima normal. Las demás opciones son de otras entidades: puentes fibrosos de cirrosis, necrosis de hepatocitos de hepatitis aguda, aumento de hierro de hemocromatosis e infiltrado linfocítico portal de hepatitis crónica. El diagnóstico es clínico y no requiere tratamiento. Perla: Crigler-Najjar causa ictericia grave neonatal por un déficit mayor de UGT1A1.",
  "Vítek L. J Hepatol 2023;79:1049-1055 (síndrome de Gilbert revisitado); Harrison Principios de Medicina Interna 22.ª ed. (2025); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)")

Q(43, "Isocromosoma 12p en tumores germinales", "Patología testicular",
  "Los tumores de células germinales testiculares del adulto derivan de la neoplasia de células germinales in situ (GCNIS) y comparten una alteración citogenética casi constante: el isocromosoma 12p, i(12p), o la ganancia del brazo corto del cromosoma 12, presente en cerca del 80 % de los casos, sea cual sea el subtipo histológico. Ello apoya el origen común del seminoma, el carcinoma embrionario, el tumor del saco vitelino, el coriocarcinoma y el teratoma. La revisión de Fichtner de 2026 en Histopathology actualiza esta base molecular y destaca que los tumores prepuberales, que no derivan de GCNIS, carecen de esta alteración. El caso describe un tumor mixto en un varón joven con aumento indoloro del testículo, que es la presentación típica. Los otros brazos cromosómicos no son característicos. Según la guía de la Asociación Europea de Urología de 2023, el estudio incluye marcadores séricos (AFP, hCG y LDH) antes y después de la orquiectomía, y el coriocarcinoma, con hCG muy elevada, produce ginecomastia y metástasis hematógenas tempranas a pulmón. El tratamiento es la orquiectomía radical inguinal, sin biopsia transescrotal, seguida de vigilancia o quimioterapia con cisplatino (BEP) según el estadio y el grupo pronóstico. Perla: el seminoma puro no eleva la AFP, y el coriocarcinoma es el de diseminación más precoz.",
  "Patrikidou A et al. Eur Urol 2023;84:289-301 (guía EAU de cáncer testicular, actualización 2023); Fichtner A et al. Histopathology 2026;88:214-229 (patología molecular de los tumores germinales testiculares); WHO Classification of Tumours, Urinary and Male Genital Tumours 5.ª ed. (2022); Oosterhuis JW, Looijenga LHJ. Nat Rev Cancer 2005;5:210-22; Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)")

Q(44, "Actinomicosis y dispositivo intrauterino", "Patología ginecológica e infecciosa",
  "Actinomyces israelii y otras especies son bacilos grampositivos anaerobios o microaerófilos, ramificados, que forman parte de la flora de la boca, el tubo digestivo y, con menor frecuencia, el tracto genital femenino. Rara vez causan enfermedad, pero una barrera mucosa dañada o un cuerpo extraño favorecen la infección. El dispositivo intrauterino, sobre todo cuando se mantiene durante años, actúa como cuerpo extraño que crea un microambiente de baja tensión de oxígeno y biopelícula, lo que facilita la colonización por Actinomyces y explica la respuesta correcta. La colonización suele ser asintomática y se detecta en la citología cervical como colonias filamentosas en «bola de algodón»; la infección invasiva produce enfermedad inflamatoria pélvica, absceso tuboovárico, masas que simulan neoplasia y fístulas con gránulos de azufre, como muestran casos de 2024 y 2025. Los otros mecanismos no existen: no hay intercambio de proteoglucanos entre membranas, transporte de entactina ni ruptura de la bicapa lipídica. El tratamiento de la enfermedad invasiva es penicilina G o amoxicilina durante varios meses, con retiro del dispositivo y drenaje si hay absceso. Perla: sin síntomas, el hallazgo citológico no obliga a retirar el DIU.",
  "Hernández-Alonso R et al. Rev Esp Enferm Dig 2024;116:714-716 (actinomicosis pélvica secundaria a dispositivo intrauterino); Pereira M et al. Cureus 2025;17:e80839 (actinomicosis pélvica relacionada con dispositivo intrauterino); Valour F et al. Infect Drug Resist 2014;7:183-97 (actinomicosis); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)",
  "Opciones redactadas de forma poco precisa; la clave oficial es el microambiente anaerobio creado por el cuerpo extraño. No se halló guía peruana vigente específica.")

Q(45, "Tiroides estimulada por TSH", "Patología endocrina",
  "La TSH se une a su receptor acoplado a proteína Gs en la membrana basolateral de las células foliculares y activa la adenilato ciclasa, con aumento del AMP cíclico. Esto estimula la captación de yoduro por el cotransportador sodio-yoduro, la síntesis de tiroglobulina, la yodación y el crecimiento celular. La glándula estimulada tiene células foliculares altas, en forma de columna, con hipertrofia e hiperplasia, a veces con papilas hacia la luz, coloide escaso con bordes festoneados por reabsorción activa y mayor vascularización. En la enfermedad de Graves, la revisión de Chaker de 2024 en Lancet resume que el estímulo proviene de anticuerpos estimulantes contra el receptor de TSH, por lo que la TSH sérica está suprimida y la glándula se comporta como si estuviera sobreestimulada; su tratamiento incluye antitiroideos, yodo radiactivo o tiroidectomía. En la glándula en reposo o inhibida, las células son planas o cúbicas, los folículos grandes y el coloide abundante, de modo que la abundancia de coloide no corresponde a la estimulación. Las células foliculares aumentan, no se reducen; las células parafoliculares (C) producen calcitonina y no responden a la TSH; y los capilares perifoliculares aumentan por el efecto trófico. Perla: el bocio por déficit de yodo resulta de la estimulación crónica por TSH ante una T4 baja.",
  "Chaker L et al. Lancet 2024;403:768-780 (hipertiroidismo); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Guyton y Hall Tratado de Fisiología Médica 14.ª ed. (2021)", "No se halló guía peruana vigente específica sobre este tema fisiopatológico.")

Q(46, "Pronóstico de los linfomas: ALCL ALK positivo", "Hematopatología",
  "El linfoma anaplásico de células grandes con translocación de ALK (t(2;5), NPM1::ALK) es un linfoma T periférico de personas jóvenes, con células grandes de aspecto pleomórfico, núcleos en herradura (células «hallmark») y expresión fuerte de CD30 y de ALK, a menudo extraganglionar y con síntomas B. Tiene mejor pronóstico que otros linfomas T: en la serie de Savage, la supervivencia a 5 años fue de 70 % en el ALK positivo y de 49 % en el ALK negativo. La guía ESMO-EHA de 2025 sobre linfomas T y NK periféricos mantiene la quimioterapia tipo CHOP como base y reconoce el esquema con brentuximab vedotina (BV-CHP) para el linfoma anaplásico CD30 positivo; en niños y adolescentes, las revisiones de 2025 informan sobrevida libre de evento de cerca del 70-75 %. La OMS 2022 conserva la distinción entre ALK positivo y negativo. El linfoma linfoplasmocítico (MYD88 L265P), el de la zona marginal y el de células del manto (t(11;14), ciclina D1) son indolentes o intermedios, pero rara vez curables; el linfoma de Burkitt (t(8;14), MYC) es de alta agresividad, curable en niños con quimioterapia intensiva y con peor evolución en adultos mayores. Perla: la expresión de ALK es un factor pronóstico favorable en el linfoma anaplásico.",
  "d'Amore F et al. Ann Oncol 2025;36:626-644 (guía ESMO-EHA de linfomas T y NK periféricos); Marks LJ et al. Blood Adv 2025;9:4870-4880 (linfoma anaplásico de células grandes pediátrico); Alaggio R et al. Leukemia 2022;36:1720-48 (WHO 5.ª ed. de neoplasias hematolinfoides); Savage KJ et al. Blood 2008;111:5496-504",
  "Pregunta comparativa de supervivencia; el linfoma de la zona marginal y el linfoplasmocítico tienen buena supervivencia global, pero la clave oficial (B) es el linfoma anaplásico ALK positivo. No se halló guía peruana específica.")

Q(47, "Duodenitis péptica", "Patología digestiva",
  "La duodenitis péptica es la lesión inflamatoria del bulbo duodenal causada por la agresión del ácido gástrico, a menudo asociada a infección por Helicobacter pylori o al uso de AINE. La hipersecreción ácida sobrepasa la neutralización por el bicarbonato duodenal, y el epitelio responde con metaplasia gástrica (epitelio foveolar en el bulbo), que puede ser colonizada por H. pylori. Los hallazgos del caso la caracterizan: aplanamiento velloso focal, infiltrado de neutrófilos y plasmocitos en la lámina propia e hiperplasia de glándulas de Brunner, que secretan moco alcalino. La clínica incluye dolor epigástrico y hemorragia digestiva alta. La enfermedad celíaca muestra atrofia vellosa difusa con linfocitosis intraepitelial e hiperplasia de criptas; la enfermedad de Crohn, granulomas no caseificantes e inflamación transmural; el esprúe tropical, atrofia en residentes de zonas tropicales; y la macroglobulinemia de Waldenström, infiltración por linfocitos plasmocitoides con IgM. Según la guía del American College of Gastroenterology de 2024, la infección por H. pylori se trata con terapia cuádruple con bismuto durante 14 días como esquema empírico de primera línea, evitando la triple con claritromicina si no se conoce la sensibilidad, y se confirma la erradicación después. Los inhibidores de la bomba de protones tratan la lesión ácida. Perla: la metaplasia gástrica duodenal es una respuesta a la agresión ácida.",
  "Chey WD et al. Am J Gastroenterol 2024;119:1730-1753 (guía ACG de tratamiento de la infección por Helicobacter pylori); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Sabiston Tratado de Cirugía 21.ª ed. (2021)", "No se halló guía peruana vigente específica sobre duodenitis.")

Q(48, "Hipotiroidismo congénito (cretinismo)", "Patología endocrina",
  "El hipotiroidismo congénito no tratado, antes llamado cretinismo, es la causa prevenible más importante de discapacidad intelectual. La hormona tiroidea (tiroxina, T4, y su forma activa T3) es indispensable para la maduración del sistema nervioso central, con mielinización, desarrollo de dendritas y migración neuronal, en el último trimestre del embarazo y los primeros años de vida, y para el crecimiento óseo. Su ausencia produce retraso del crecimiento, talla baja, rasgos faciales toscos con macroglosia (protrusión de la lengua), hernia umbilical, piel seca, ictericia prolongada, estreñimiento e hipotonía, y discapacidad intelectual grave si el tratamiento se retrasa. Las causas son disgenesia tiroidea, el defecto de la síntesis hormonal (dishormonogénesis) y, en áreas endémicas, la deficiencia de yodo. La deficiencia de cortisol causa hipoglucemia y colapso; la de noradrenalina no se asocia a un síndrome así; la somatostatina inhibe hormonas, y la deficiencia de insulina produce hiperglucemia. El tamizaje neonatal mide TSH en sangre del talón antes del séptimo día, según la NTS 154-MINSA/2019/DGIESP, y el tratamiento con levotiroxina desde las primeras 2 semanas evita las secuelas. Perla: los síntomas aparecen después de los 2-3 meses, por lo que sin tamizaje se pierde la ventana terapéutica.",
  ROB + "; Nelson Tratado de Pediatría 22.ª ed. (2024); NTS 154-MINSA/2019/DGIESP (tamizaje neonatal)")

Q(49, "Leucemia de células peludas", "Hematopatología",
  "La leucemia de células peludas es una neoplasia indolente de linfocitos B maduros que predomina en varones de edad media, con pancitopenia, esplenomegalia sin adenopatías y monocitopenia característica; el caso describe a una mujer, que es menos frecuente. Se debe a la mutación BRAF V600E, presente en casi todos los casos clásicos, según la revisión de Falini de 2024 en N Engl J Med. En el bazo infiltra la pulpa roja de forma difusa, con células de citoplasma claro y prolongaciones, y la médula es difícil de aspirar («punción seca») por fibrosis reticulínica. El fenotipo es CD20, CD11c, CD103, CD25, anexina A1, TRAP y CD123 positivos. La leucemia mieloide crónica tiene BCR::ABL1; el linfoma difuso de células B grandes forma masas con células grandes; la leucemia linfocítica crónica expresa CD5 y CD23; y el linfoma esplénico de la zona marginal es CD103 y anexina A1 negativos y afecta la pulpa blanca. La OMS 2022 reemplazó la antigua variante de células peludas por el linfoma/leucemia B esplénico con nucleolos prominentes, entidad BRAF negativa. El tratamiento es cladribina o pentostatina, con remisión en la gran mayoría, y en las recaídas, inhibidores de BRAF como vemurafenib, con o sin rituximab. Perla: la anexina A1 es el marcador más específico frente a otros linfomas B.",
  "Falini B et al. N Engl J Med 2024;391:1328-1341 (leucemia de células peludas); Mendez-Hernandez A et al. Curr Oncol Rep 2023;25:833-840 (leucemia de células peludas en 2023); Naresh KN et al. Br J Haematol 2024;205:2142-2152 (linfoma/leucemia B esplénico con nucleolos prominentes); Alaggio R et al. Leukemia 2022;36:1720-48 (WHO 5.ª ed. de neoplasias hematolinfoides); Tiacci E et al. N Engl J Med 2011;364:2305-15; Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)", "No se halló guía peruana vigente específica. El texto del enunciado habla de «linfoma esplénico con linfocitos vellosos», término previo a la OMS 2022.")

Q(50, "Eritema nodoso", "Dermatopatología",
  "El eritema nodoso es la paniculitis más frecuente. Es una reacción de hipersensibilidad tardía a diversos estímulos y se presenta como nódulos dolorosos, eritematosos y calientes en la cara anterior de las piernas, sobre todo en mujeres jóvenes, a veces con fiebre y artralgias; no se localiza en la cara. Histológicamente es una paniculitis septal sin vasculitis: los septos del tejido adiposo subcutáneo se ensanchan por edema e infiltrado de linfocitos, histiocitos y neutrófilos, con granulomas de Miescher radiales, mientras que el lobulillo graso se conserva. No es una anaerobiosis granulomatosa ni una paniculitis lobulillar, que corresponde a la deficiencia de alfa-1 antitripsina, la paniculitis lúpica y la necrosis grasa. La cohorte de Shah de 2024 en JAMA Dermatol, y la revisión alemana de Weber de 2024, muestran que el cuadro puede ser idiopático en una parte importante de los casos y que algunos pacientes evolucionan a cronicidad o recurrencia. Las causas más comunes son las infecciones estreptocócicas, la tuberculosis y otras micobacteriosis, la sarcoidosis (síndrome de Löfgren), la enfermedad inflamatoria intestinal, los fármacos (anticonceptivos orales, sulfonamidas) y el embarazo. El tratamiento consiste en tratar la causa, reposo, AINE y yoduro de potasio, y suele resolverse en 3-6 semanas sin cicatriz. En el Perú, la NTS 221-MINSA/DGIESP-2024 rige el diagnóstico de la tuberculosis cuando se sospecha esta causa. Perla: ante un eritema nodoso, se investiga estreptococo, tuberculosis y sarcoidosis.",
  "Shah JT et al. JAMA Dermatol 2024;160:229-232 (características clínicas del eritema nodoso y su asociación con cronicidad y recurrencia); Weber V et al. Z Rheumatol 2024;83:641-649 (eritema nodoso); NTS 221-MINSA/DGIESP-2024 (tuberculosis); Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021); Requena L, Yus ES. J Am Acad Dermatol 2001;45:163-83")
